import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int h = scanner.nextInt();
        int n = scanner.nextInt();
        scanner.nextLine(); // consume the remaining newline

        String N = Integer.toBinaryString(n - 1);
        int lengthDifference = h - N.length();
        StringBuilder NBuilder = new StringBuilder();
        for (int i = 0; i < lengthDifference; i++) {
            NBuilder.append('0');
        }
        NBuilder.append(N);
        N = NBuilder.toString();

        int total_moves = 0;
        boolean flip_flag = false;

        for (int index = 0; index < h; index++) {
            char expected_char = flip_flag ? '0' : '1';
            if (N.charAt(index) != expected_char) {
                flip_flag = !flip_flag;
                total_moves += 1;
            } else {
                total_moves += Math.pow(2, h - index);
            }
        }
        System.out.println(total_moves);
    }
}
